<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Farming Game</title>
    <style>
        canvas {
            border: 1px solid black;
        }
    </style>
</head>
<body>
    <canvas id="gameCanvas" width="800" height="600"></canvas>
    <script>
        const canvas = document.getElementById('gameCanvas');
        const ctx = canvas.getContext('2d');

        let player = { x: 0, y: 0 };
        let tiles = {};
        let inventory = { seeds: 5, crops: 0 };
        let day = 0;

        function drawPlayer() {
            ctx.fillStyle = 'green';
            ctx.fillRect(player.x, player.y, 10, 10);
        }

        function drawTiles() {
            for (const tile in tiles) {
                const { crop, stage } = tiles[tile];
                ctx.fillStyle = crop === 'seed' ? 'red' : 'green';
                ctx.fillRect(tile.split(',')[0], tile.split(',')[1], 10, 10);
            }
        }

        function drawInventory() {
            ctx.fillStyle = 'blue';
            ctx.fillText(`Seeds: ${inventory.seeds}`, 10, 20);
            ctx.fillText(`Crops: ${inventory.crops}`, 10, 40);
        }

        function drawDay() {
            ctx.fillStyle = 'purple';
            ctx.fillText(`Day: ${day}`, 10, 60);
        }

        function update() {
            requestAnimationFrame(update);
            day++;
            drawDay();
        }

        function handleKeyDown(event) {
            switch (event.key) {
                case 'ArrowUp':
                    player.y -= 10;
                    break;
                case 'ArrowDown':
                    player.y += 10;
                    break;
                case 'ArrowLeft':
                    player.x -= 10;
                    break;
                case 'ArrowRight':
                    player.x += 10;
                    break;
                case 'p':
                    if (inventory.seeds > 0) {
                        inventory.seeds--;
                        tiles[player.x + ',' + player.y] = { crop: 'seed', stage: 0 };
                    }
                    break;
                case 't':
                    // Implement time advancement logic here
                    break;
                case 'h':
                    if (tiles[player.x + ',' + player.y].crop === 'seed') {
                        inventory.crops++;
                        delete tiles[player.x + ',' + player.y];
                    }
                    break;
                case 's':
                    localStorage.setItem('gameState', JSON.stringify({ player, tiles, inventory, day }));
                    break;
                case 'l':
                    const savedState = localStorage.getItem('gameState');
                    if (savedState) {
                        const state = JSON.parse(savedState);
                        player = state.player;
                        tiles = state.tiles;
                        inventory = state.inventory;
                        day = state.day;
                    }
                    break;
            }
            drawPlayer();
            drawTiles();
            drawInventory();
        }

        document.addEventListener('keydown', handleKeyDown);

        update();
    </script>
</body>
</html>
